//! Cache A/B harness. Runs the same CPU-bound pure effect K times over
//! M unique keys, once with caching off and once with caching on. Prints
//! per-pass wall, telemetry rollup, `CacheStats`, and RSS.
//!
//! The effect is `ScanBlob { id }` — picks a generated byte blob out of
//! an in-memory store, counts occurrences of a fixed needle. Wrapped in
//! `WorkSteal` so the compute path exercises the rayon pool.
//!
//! Same run structure both ways, only difference is the registration
//! call. This is the shape every future cache A/B should follow.
//!
//! Usage:
//!   cache_ab_bench --blobs 2000 --size 16384 --passes 5 --workers 8 --cap 4096 --cache on|off
//!
//! Compare two runs by diffing their output. `--cache off` is the
//! baseline; `--cache on` reports hit ratio and RSS delta.

#[global_allocator]
static GLOBAL: tikv_jemallocator::Jemalloc = tikv_jemallocator::Jemalloc;

use effect_runtime::batchers::{CacheLayer, WorkSteal};
use effect_runtime::{
    Batcher, BoxFuture, CancellationToken, EffectKind, PureEffect, RtCtx, RtCtxBuilder,
};
use std::collections::HashMap;
use std::sync::Arc;
use std::time::Instant;

pub struct ScanBlob {
    pub id: u64,
}
impl EffectKind for ScanBlob {
    type Response = u64;
    fn payload_bytes(&self) -> Option<usize> { None }
    fn response_bytes(_r: &Self::Response) -> Option<usize> { Some(8) }
}
impl PureEffect for ScanBlob {
    type Key = u64;
    const DOMAIN: &'static str = "scanblob";
    fn cache_key(&self) -> u64 { self.id }
}

/// Inner batcher. Matches the shape of `topology_choice::count_needle`
/// but keyed by id so identical keys produce identical work.
struct BlobScanner {
    blobs: Arc<HashMap<u64, Vec<u8>>>,
    needle: Vec<u8>,
}
fn count_needle(hay: &[u8], nd: &[u8]) -> u64 {
    if nd.is_empty() || nd.len() > hay.len() { return 0; }
    let mut n: u64 = 0;
    for i in 0..=(hay.len() - nd.len()) {
        if &hay[i..i + nd.len()] == nd { n += 1; }
    }
    n
}
impl Batcher<ScanBlob> for BlobScanner {
    fn run(&self, req: ScanBlob, _cancel: CancellationToken) -> BoxFuture<'static, u64> {
        let blobs = self.blobs.clone();
        let needle = self.needle.clone();
        Box::pin(async move {
            match blobs.get(&req.id) {
                Some(bytes) => count_needle(bytes, &needle),
                None => 0,
            }
        })
    }
}

fn gen_blobs(count: u64, size: usize) -> HashMap<u64, Vec<u8>> {
    let mut out = HashMap::with_capacity(count as usize);
    let needle = b"printk";
    for id in 0..count {
        let mut v = Vec::with_capacity(size);
        let tag = format!("blob-{}-", id).into_bytes();
        while v.len() + tag.len() + needle.len() + 8 < size {
            v.extend_from_slice(&tag);
            v.extend_from_slice(needle);
            v.extend_from_slice(b"____");
        }
        while v.len() < size { v.push(b'.'); }
        out.insert(id, v);
    }
    out
}

fn rss_peak_kb() -> u64 {
    unsafe {
        let mut u: libc::rusage = std::mem::zeroed();
        if libc::getrusage(libc::RUSAGE_SELF, &mut u) != 0 { return 0; }
        #[cfg(target_os = "macos")]
        { (u.ru_maxrss as u64) / 1024 }
        #[cfg(not(target_os = "macos"))]
        { u.ru_maxrss as u64 }
    }
}

async fn run_pass(ctx: &RtCtx, blobs: u64) -> (f64, u64) {
    let t0 = Instant::now();
    let mut handles = Vec::with_capacity(blobs as usize);
    for id in 0..blobs {
        let ctx = ctx.clone();
        handles.push(tokio::spawn(async move { ctx.put(ScanBlob { id }).await }));
    }
    let mut total: u64 = 0;
    for h in handles { total += h.await.unwrap(); }
    (t0.elapsed().as_secs_f64() * 1000.0, total)
}

#[derive(Default)]
struct Args {
    blobs: u64,
    size: usize,
    passes: u32,
    workers: usize,
    cap: u64,
    cache: bool,
    needle: Vec<u8>,
}

fn parse_args() -> Args {
    let mut a = Args {
        blobs: 2000, size: 16_384, passes: 5, workers: 8, cap: 4096,
        cache: false, needle: b"printk".to_vec(),
    };
    let mut it = std::env::args().skip(1);
    while let Some(flag) = it.next() {
        match flag.as_str() {
            "--blobs"   => a.blobs   = it.next().unwrap().parse().unwrap(),
            "--size"    => a.size    = it.next().unwrap().parse().unwrap(),
            "--passes"  => a.passes  = it.next().unwrap().parse().unwrap(),
            "--workers" => a.workers = it.next().unwrap().parse().unwrap(),
            "--cap"     => a.cap     = it.next().unwrap().parse().unwrap(),
            "--cache"   => a.cache   = matches!(it.next().as_deref(), Some("on" | "true" | "1")),
            other       => eprintln!("unknown flag: {}", other),
        }
    }
    a
}

#[tokio::main(flavor = "multi_thread")]
async fn main() {
    let a = parse_args();
    let blobs = Arc::new(gen_blobs(a.blobs, a.size));
    let total_bytes = a.blobs as usize * a.size;
    println!(
        "# config: blobs={} size={} total_MB={:.1} passes={} workers={} cap={} cache={}",
        a.blobs,
        a.size,
        total_bytes as f64 / 1_048_576.0,
        a.passes,
        a.workers,
        a.cap,
        if a.cache { "on" } else { "off" },
    );
    let rss_before_ctx = rss_peak_kb();

    let scanner = BlobScanner { blobs: blobs.clone(), needle: a.needle.clone() };
    let work_steal = WorkSteal::<ScanBlob, _>::new(a.workers, move |r: ScanBlob| {
        match scanner.blobs.get(&r.id) {
            Some(b) => count_needle(b, &scanner.needle),
            None => 0,
        }
    });

    let (ctx, stats_handle): (RtCtx, Option<CacheLayer<ScanBlob>>) = if a.cache {
        let layer = CacheLayer::<ScanBlob>::new(a.cap, work_steal);
        let handle = layer.clone();
        let ctx = RtCtxBuilder::new()
            .register_domain_aware::<ScanBlob, _>(layer)
            .build();
        (ctx, Some(handle))
    } else {
        let ctx = RtCtxBuilder::new()
            .register::<ScanBlob, _>(work_steal)
            .build();
        (ctx, None)
    };

    println!("# rss_kb: before_ctx={} after_ctx={}", rss_before_ctx, rss_peak_kb());

    for p in 1..=a.passes {
        let (wall_ms, total_matches) = run_pass(&ctx, a.blobs).await;
        let stats = stats_handle.as_ref().map(|h| h.stats());
        let rss = rss_peak_kb();
        let mb_s = (total_bytes as f64 / 1_048_576.0) / (wall_ms / 1000.0);
        let stats_line = match stats {
            Some(s) => format!(
                " hits={} misses={} entries={} hit_ratio={:.3}",
                s.hits, s.misses, s.entries, s.hit_ratio(),
            ),
            None => String::new(),
        };
        println!(
            "pass={} wall_ms={:.1} MB/s={:.1} matches={} rss_kb={}{}",
            p, wall_ms, mb_s, total_matches, rss, stats_line,
        );
    }

    print!("{}", ctx.telemetry().summary());
}
